pm.test("La respuesta JSON contiene al menos 1 artículo", function () {
    const json = pm.response.json();
    const items = Array.isArray(json)
        ? json
        : ["products", "data", "items", "results"]
            .map(function (key) { return json && json[key]; })
            .find(Array.isArray);

    pm.expect(items, "Se esperaba un arreglo directo o en products, data, items o results").to.be.an("array");
    pm.expect(items.length, "El arreglo de artículos está vacío").to.be.above(0);
});

// ── Catálogo de productos tecnológicos realistas ──────────────────────────────
const catalog = [
  {
