    description: "Teclado inalámbrico de perfil bajo con retroiluminación inteligente, compatible con Windows, macOS y Linux.",
    attributes: [{ color: "Grafito" }, { layout: "ES" }, { connectivity: "Bluetooth / USB-C" }],
    priceMin: 109.99, priceMax: 139.99,
    tax: "21.00",
    imageSlug: "keyboard"
  },
  {
    name: "Monitor LG UltraWide 34WP65C",
    model: "34WP65C-B",
    brand: "LG",
    brandId: 7,
    category: ["electronics", "monitors", "displays"],
    description: "Monitor curvo UltraWide 21:9 de 34 pulgadas, resolución WQHD 3440×1440, panel VA con HDR10 y AMD FreeSync Premium.",
    attributes: [{ size: "34 pulgadas" }, { resolution: "3440x1440" }, { panel: "VA" }],
    priceMin: 399.99, priceMax: 499.99,
    tax: "21.00",
    imageSlug: "monitor"
  },
  {
    name: "Cámara Web Logitech StreamCam",
    model: "StreamCam",
    brand: "Logitech",
    brandId: 5,
    category: ["electronics", "cameras", "webcams"],
    description: "Cámara web Full HD 1080p/60fps con autoenfoque inteligente por IA, ideal para streaming y videoconferencias.",
    attributes: [{ resolution: "1080p 60fps" }, { connection: "USB-C" }, { autofocus: "IA" }],
    priceMin: 89.99, priceMax: 129.99,
    tax: "21.00",
    imageSlug: "camera"
  },
  {
    name: "Altavoz Portátil JBL Charge 5",
    model: "Charge 5",
    brand: "JBL",
    brandId: 9,
    category: ["electronics", "audio", "speakers"],
    description: "Altavoz Bluetooth portátil resistente al agua IP67, 20 h de reproducción y función de carga para dispositivos móviles.",
    attributes: [{ color: "Azul" }, { waterproof: "IP67" }, { battery: "20 horas" }],
    priceMin: 149.99, priceMax: 189.99,
    tax: "21.00",
    imageSlug: "speaker"
  },
  {
    name: "Ratón Gaming Razer DeathAdder V3",
    model: "DeathAdder V3",
    brand: "Razer",
    brandId: 11,
    category: ["electronics", "peripherals", "mice"],
    description: "Ratón gaming ergonómico ultraligero de 59 g con sensor óptico Focus Pro 30K y hasta 90 h de batería inalámbrica.",
    attributes: [{ weight: "59g" }, { dpi: "30000" }, { connectivity: "HyperSpeed Wireless" }],
    priceMin: 79.99, priceMax: 109.99,
