    attributes: [{ capacity: "1 TB" }, { interface: "USB 3.2 Gen 2" }, { color: "Beige" }],
    priceMin: 89.99, priceMax: 119.99,
    tax: "21.00",
    imageSlug: "ssd"
  }
];

const statuses = ["In Stock", "Out of Stock", "Pre-order", "Limited Stock"];

// ── Selección aleatoria ───────────────────────────────────────────────────────
const idx  = Math.floor(Math.random() * catalog.length);
const item = catalog[idx];

const price    = (item.priceMin + Math.random() * (item.priceMax - item.priceMin)).toFixed(2);
const quantity = Math.floor(Math.random() * 200) + 1;
const rating   = (3.5 + Math.random() * 1.5).toFixed(2);
const status   = statuses[Math.floor(Math.random() * statuses.length)];
const seed     = Math.floor(Math.random() * 9000) + 1000;   // semilla para imagen
const imageUrl = `https://picsum.photos/seed/${item.imageSlug}${seed}/640/480`;
const slug     = item.name.toLowerCase().replace(/\s+/g, "-").replace(/[^a-z0-9-]/g, "");
const productUrl = `https://www.store1.geekqa.net/products/${slug}`;
const now      = new Date().toISOString();

// ── Guardar variables locales ─────────────────────────────────────────────────
pm.variables.set("gen_products_name",          item.name);
pm.variables.set("gen_products_status",        status);
pm.variables.set("gen_products_model",         item.model);
pm.variables.set("gen_products_url",           productUrl);
pm.variables.set("gen_products_quantity",      String(quantity));
pm.variables.set("gen_products_price_ex_tax",  price);
pm.variables.set("gen_products_tax_percentage",item.tax);
pm.variables.set("gen_products_rating",        rating);
pm.variables.set("gen_products_description",   item.description);
pm.variables.set("gen_products_brand_name",    item.brand);
pm.variables.set("gen_products_brand_id",      String(item.brandId));
pm.variables.set("gen_products_thumbnail",     imageUrl);
pm.variables.set("gen_products_categories",    JSON.stringify(item.category));
pm.variables.set("gen_products_attributes",    JSON.stringify(item.attributes));
pm.variables.set("gen_updated_at",             now);

console.log(`[Pre-request] Producto generado: ${item.name} | Precio: ${price} | Estado: ${status}`);

// ── Test: Creación exitosa ────────────────────────────────────────────────────
pm.test("Status 201 - Producto creado exitosamente", function () {
    pm.response.to.have.status(201);
});

// ── Test: Respuesta es JSON válido ────────────────────────────────────────────
pm.test("La respuesta es JSON válido", function () {
    pm.response.to.be.json;
});

// ── Test: El cuerpo contiene mensaje de éxito ─────────────────────────────────
pm.test("El cuerpo contiene mensaje de creación", function () {
    const json = pm.response.json();
    pm.expect(json).to.have.property("message");
    pm.expect(json.message).to.include("created");
});

// ── Test: El producto devuelto tiene el nombre generado ───────────────────────
pm.test("El producto devuelto coincide con el nombre generado", function () {
    const json = pm.response.json();
    pm.expect(json).to.have.property("product");
    pm.expect(json.product.products_name).to.eql(pm.variables.get("gen_products_name"));
});

// ── Test: El producto tiene ID asignado ───────────────────────────────────────
pm.test("El producto tiene un ID asignado", function () {
    const json = pm.response.json();
    pm.expect(json.product).to.have.property("id");
    pm.expect(json.product.id).to.be.a("number");
});

// ── Test: La URL de imagen es HTTPS ───────────────────────────────────────────
pm.test("La URL de imagen es HTTPS", function () {
    const json = pm.response.json();
    pm.expect(json.product.products_thumbnail).to.match(/^https:\/\//);
});
